//! Mirrors the shared Python grading rules; fixtures are generated by Python.
use anyhow::{Result, bail};
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};

#[derive(Clone, Debug, Deserialize)]
pub struct Submission {
    pub question_index: usize,
    pub question_token: Option<String>,
    pub answer: Value,
    pub complex_answer: Option<Vec<Value>>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Answer {
    pub username: String,
    pub answer: String,
    pub right: bool,
    pub time_taken: f64,
    pub score: i64,
}

pub fn grade(question: &Value, data: &Submission) -> Result<(bool, String)> {
    let mut answer = match &data.answer {
        Value::String(v) => v.clone(),
        Value::Number(v) if v.is_i64() || v.is_u64() => v.to_string(),
        _ => bail!("answer must be a string or integer"),
    };
    if answer.len() > 16_384 {
        bail!("answer too long");
    }
    let choices = question["answers"].as_array();
    let right = match question["type"].as_str().unwrap_or("ABCD") {
        "ABCD" => choices.is_some_and(|rows| {
            rows.iter()
                .any(|r| r["answer"] == answer && r["right"] == true)
        }),
        "CHECK" => {
            let expected: String = choices
                .ok_or_else(|| anyhow::anyhow!("missing choices"))?
                .iter()
                .enumerate()
                .filter(|(_, r)| r["right"] == true)
                .map(|(i, _)| i.to_string())
                .collect();
            answer == expected
        }
        "TEXT" => choices.is_some_and(|rows| {
            rows.iter().any(|r| {
                let expected = r["answer"].as_str().unwrap_or("");
                if r["case_sensitive"] == true {
                    answer == expected
                } else {
                    answer.to_lowercase() == expected.to_lowercase()
                }
            })
        }),
        "RANGE" => {
            let value: f64 = answer.trim().parse()?;
            if !value.is_finite() {
                bail!("non-finite range answer");
            }
            let value = value.trunc(); // Python int(float(answer)), including negatives.
            value
                >= question["answers"]["min_correct"]
                    .as_f64()
                    .unwrap_or(f64::INFINITY)
                && value
                    <= question["answers"]["max_correct"]
                        .as_f64()
                        .unwrap_or(f64::NEG_INFINITY)
        }
        "ORDER" => {
            if let Some(order) = &data.complex_answer {
                if order.len() > 1024 {
                    bail!("order too long");
                }
                let expected: Vec<Value> = choices
                    .ok_or_else(|| anyhow::anyhow!("missing order"))?
                    .iter()
                    .map(|r| json!({"answer":r["answer"]}))
                    .collect();
                let submitted: Vec<Value> = order
                    .iter()
                    .map(|r| json!({"answer":r["answer"]}))
                    .collect();
                let words: Result<Vec<&str>> = order
                    .iter()
                    .map(|r| {
                        r["answer"]
                            .as_str()
                            .ok_or_else(|| anyhow::anyhow!("invalid order"))
                    })
                    .collect();
                answer = words?.join(", ");
                submitted == expected
            } else {
                false
            }
        }
        "VOTING" | "SLIDE" => false,
        _ => bail!("unsupported question type"),
    };
    if answer.len() > 16384 {
        bail!("normalized answer too long");
    }
    Ok((right, answer))
}

pub fn score(right: bool, elapsed_ms: f64, duration_secs: f64) -> i64 {
    if !right || duration_secs <= 0.0 {
        return 0;
    }
    ((1000.0 * (1.0 - elapsed_ms.max(0.0) / (duration_secs.trunc() * 1000.0))) as i64)
        .clamp(0, 1000)
}

pub fn public_question(question: &Value) -> Value {
    let mut q = question.clone();
    if q["type"] == "RANGE" {
        q["answers"] = json!({"min":q["answers"]["min"], "max":q["answers"]["max"]});
    } else if let Some(rows) = q["answers"].as_array_mut() {
        let voting = question["type"] == "VOTING";
        for row in rows.iter_mut() {
            let answer = row["answer"].clone();
            let color = row["color"].clone();
            let image = row["image"].clone();
            *row = if voting {
                json!({"answer":answer,"color":color,"image":image})
            } else {
                json!({"answer":answer, "color":color})
            };
        }
        if q["type"] == "ORDER" {
            use rand::seq::SliceRandom;
            q["answers"]
                .as_array_mut()
                .unwrap()
                .shuffle(&mut rand::rng());
        }
    }
    q
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn shared_python_fixtures() {
        let fixtures: Vec<Value> =
            serde_json::from_str(include_str!("../tests/grading.json")).unwrap();
        assert!(
            fixtures.len() >= 30,
            "generate the shared Python grading fixtures first"
        );
        for f in fixtures {
            let data: Submission = serde_json::from_value(f["submission"].clone()).unwrap();
            let actual = grade(&f["question"], &data);
            if f["error"] == true {
                assert!(actual.is_err(), "{f}");
            } else {
                assert_eq!(json!(actual.unwrap()), f["expected"], "{f}");
            }
        }
    }
    #[test]
    fn score_bounds_and_public_secrets() {
        assert_eq!(score(true, -20.0, 30.0), 1000);
        assert_eq!(score(true, 100000.0, 30.0), 0);
        let q =
            json!({"type":"RANGE","answers":{"min":0,"max":10,"min_correct":5,"max_correct":6}});
        assert!(public_question(&q)["answers"].get("min_correct").is_none());
        let voting =
            json!({"type":"VOTING","answers":[{"answer":"A","image":"image-id","color":"red"}]});
        assert_eq!(public_question(&voting)["answers"][0]["image"], "image-id");
    }
}
